1	import bcrypt from "bcryptjs";
2	
3	export type User = {
4	  id: string;
5	  email: string;
6	  name: string;
7	  createdAt: string;
8	  // Absent for users who only ever signed in via an OAuth provider (e.g. Google).
9	  passwordHash?: string;
10	};
11	
12	// Next.js (Turbopack, in both dev and prod) can load this module more than once —
13	// route handlers and page renders don't always land in the same module instance.
14	// Pin the store on globalThis so every instance reads/writes the same array within
15	// this process; otherwise sign-ups made via /api/signup silently "vanish" when the
16	// dashboard re-reads users through a different copy of this module.
17	const globalForUsers = globalThis as unknown as { __notelyUsers?: User[] };
18	
19	const users: User[] =
20	  globalForUsers.__notelyUsers ??
21	  (globalForUsers.__notelyUsers = [
22	    { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
23	    { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
24	  ]);
25	
26	export async function listUsers(): Promise<User[]> {
27	  return users;
28	}
29	
30	export async function getUser(id: string): Promise<User | undefined> {
31	  return users.find((u) => u.id === id);
32	}
33	
34	export async function getUserByEmail(email: string): Promise<User | undefined> {
35	  const normalized = email.toLowerCase();
36	  return users.find((u) => u.email.toLowerCase() === normalized);
37	}
38	
39	function nextId(): string {
40	  return String(users.length + 1);
41	}
42	
43	function today(): string {
44	  return new Date().toISOString().slice(0, 10);
45	}
46	
47	// Used by the credentials sign-up flow.
48	export async function createUser({
49	  email,
50	  name,
51	  password,
52	}: {
53	  email: string;
54	  name: string;
55	  password: string;
56	}): Promise<User> {
57	  if (await getUserByEmail(email)) {
58	    throw new Error("A user with that email already exists");
59	  }
60	  const passwordHash = await bcrypt.hash(password, 10);
61	  const user: User = {
62	    id: nextId(),
63	    email,
64	    name,
65	    createdAt: today(),
66	    passwordHash,
67	  };
68	  users.push(user);
69	  return user;
70	}
71	
72	// Used by the credentials sign-in flow. Returns the user only if the password matches.
73	export async function verifyPassword(
74	  email: string,
75	  password: string
76	): Promise<User | undefined> {
77	  const user = await getUserByEmail(email);
78	  if (!user?.passwordHash) return undefined;
79	  const valid = await bcrypt.compare(password, user.passwordHash);
80	  return valid ? user : undefined;
81	}
82	
83	// Used by OAuth providers (e.g. Google): find the existing account by email, or
84	// provision one on first sign-in. OAuth-only users have no passwordHash, so they
85	// can't also be logged into via the credentials form.
86	export async function findOrCreateOAuthUser({
87	  email,
88	  name,
89	}: {
90	  email: string;
91	  name: string;
92	}): Promise<User> {
93	  const existing = await getUserByEmail(email);
94	  if (existing) return existing;
95	  const user: User = { id: nextId(), email, name, createdAt: today() };
96	  users.push(user);
97	  return user;
98	}
99	
100	export async function getCurrentUser(): Promise<User | undefined> {
101	  // Imported lazily to avoid a module cycle: src/auth.ts imports from this file
102	  // (verifyPassword, findOrCreateOAuthUser) to implement its providers.
103	  const { auth } = await import("@/auth");
104	  const session = await auth();
105	  if (!session?.user?.email) return undefined;
106	  return getUserByEmail(session.user.email);
107	}
