import { getCurrentUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  const me = await getCurrentUser();
  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import Link from "next/link";
import "./globals.css";
import { auth } from "@/auth";
import { SignOutButton } from "./sign-out-button";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Notely",
  description: "Notely",
};

export default async function RootLayout({ children }: LayoutProps<"/">) {
  const session = await auth();

  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col">
        <header className="flex items-center justify-between border-b border-black/[.08] px-6 py-4 text-sm dark:border-white/[.145]">
          <Link href="/" className="font-semibold">
            Notely
          </Link>
          <nav className="flex items-center gap-4">
            {session?.user ? (
              <>
                <Link href="/dashboard" className="font-medium">
                  Dashboard
                </Link>
                <span className="text-zinc-500">{session.user.email}</span>
                <SignOutButton />
              </>
            ) : (
              <>
                <Link href="/signin" className="font-medium">
                  Sign in
                </Link>
                <Link href="/signup" className="font-medium">
                  Sign up
                </Link>
              </>
            )}
          </nav>
        </header>
        <div className="flex flex-1 flex-col">{children}</div>
      </body>
    </html>
  );
}

