import { clerkClient, currentUser } from "@clerk/nextjs/server";

export default async function DashboardPage() {
  const me = await currentUser();

  const client = await clerkClient();
  const { data: users } = await client.users.getUserList({ limit: 50 });

  return (
    <main className="mx-auto max-w-2xl p-8">
      <h1 className="text-2xl font-semibold">Dashboard</h1>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.fullName ?? me?.username ?? "nobody"} (
        {me?.primaryEmailAddress?.emailAddress ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {users.map((u) => (
          <li key={u.id} className="text-sm">
            {u.fullName ?? u.username ?? u.id} —{" "}
            {u.primaryEmailAddress?.emailAddress ?? "no email"} — joined{" "}
            {new Date(u.createdAt).toLocaleDateString()}
          </li>
        ))}
      </ul>
    </main>
  );
}

